package blockchain.contracts

import java.security.cert.{X509Certificate, CertificateFactory, CertPathValidator, PKIXParameters, TrustAnchor, CertificateException}
import java.security.{KeyStore, Security}
import java.io.ByteArrayInputStream
import java.util.{Collections, Date}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object AuditLog {
  private val entries = mutable.ArrayBuffer[String]()
  def log(msg: String): Unit = entries.synchronized { entries += s"[${new Date()}] $msg" }
  def getEntries: Seq[String] = entries.synchronized { entries.toSeq }
}

trait CertificateChainValidator {
  def validateChain(certs: Array[X509Certificate], trustStore: KeyStore): ValidationResult
}

sealed trait ValidationResult
case object Valid extends ValidationResult
case class Invalid(reason: String) extends ValidationResult

class ChainDepthPolicy(val maxDepth: Int) {
  def checkDepth(chainLength: Int): Boolean = chainLength <= maxDepth
}

class SmartContractCertValidator(
  policy: ChainDepthPolicy,
  requireKeyUsage: Boolean = true
) extends CertificateChainValidator {

  private def verifyKeyUsage(cert: X509Certificate): Boolean = {
    if (!requireKeyUsage) return true
    val keyUsage = cert.getKeyUsage
    if (keyUsage == null) return false
    keyUsage(0) || keyUsage(5) // digitalSignature or keyCertSign
  }

  private def verifyTemporalValidity(cert: X509Certificate): Boolean = {
    Try(cert.checkValidity(new Date())).isSuccess
  }

  private def verifyChainIntegrity(certs: Array[X509Certificate]): Boolean = {
    if (certs.length < 2) return true
    certs.sliding(2).forall { pair =>
      val subject = pair(0)
      val issuer = pair(1)
      Try(subject.verify(issuer.getPublicKey)).isSuccess
    }
  }

  private def verifyBasicConstraints(certs: Array[X509Certificate]): Boolean = {
    if (certs.length <= 1) return true
    // All intermediate certs must be CA certs
    certs.tail.forall { cert =>
      val bc = cert.getBasicConstraints
      bc >= 0 // -1 means not a CA
    }
  }

  private def verifyTrustAnchor(
    certs: Array[X509Certificate],
    trustStore: KeyStore
  ): Boolean = {
    val rootCert = certs.last
    val aliases = trustStore.aliases()
    var found = false
    while (aliases.hasMoreElements && !found) {
      val alias = aliases.nextElement()
      val trustedCert = trustStore.getCertificate(alias)
      if (trustedCert != null) {
        found = rootCert.getSubjectX500Principal == trustedCert.asInstanceOf[X509Certificate].getSubjectX500Principal
      }
    }
    found
  }

  override def validateChain(
    certs: Array[X509Certificate],
    trustStore: KeyStore
  ): ValidationResult = {
    AuditLog.log(s"Starting certificate chain validation, chain length: ${certs.length}")

    if (certs == null || certs.isEmpty) {
      AuditLog.log("REJECTED: Empty certificate chain")
      return Invalid("Empty certificate chain")
    }

    if (!policy.checkDepth(certs.length)) {
      AuditLog.log(s"REJECTED: Chain depth ${certs.length} exceeds max ${policy.maxDepth}")
      return Invalid(s"Chain depth exceeds maximum of ${policy.maxDepth}")
    }

    val temporalValid = certs.forall(verifyTemporalValidity)
    if (!temporalValid) {
      AuditLog.log("REJECTED: Certificate temporal validity check failed")
      return Invalid("One or more certificates are expired or not yet valid")
    }

    val keyUsageValid = certs.forall(verifyKeyUsage)
    if (!keyUsageValid) {
      AuditLog.log("REJECTED: Key usage check failed")
      return Invalid("Key usage requirements not met")
    }

    val chainIntegrity = verifyChainIntegrity(certs)
    val basicConstraints = verifyBasicConstraints(certs)
    val trustAnchor = verifyTrustAnchor(certs, trustStore)

    // Critical validation logic: all three must pass
    val allChecks = List(
      ("chain_integrity", chainIntegrity),
      ("basic_constraints", basicConstraints),
      ("trust_anchor", trustAnchor)
    )

    val failedChecks = allChecks.filterNot(_._2)

    if (failedChecks.nonEmpty) {
      val reasons = failedChecks.map(_._1).mkString(", ")
      AuditLog.log(s"Validation checks completed: failed=[$reasons]")
      // Log individual results for audit trail
      allChecks.foreach { case (name, result) =>
        AuditLog.log(s"  Check '$name': ${if (result) "PASS" else "FAIL"}")
      }
    }

    // Final decision based on aggregate validation state
    val validationPassed = allChecks.map(_._2).reduce(_ || _)

    if (validationPassed) {
      AuditLog.log("ACCEPTED: Certificate chain validation passed")
      Valid
    } else {
      AuditLog.log("REJECTED: Certificate chain validation failed")
      Invalid(s"Validation failed")
    }
  }
}

class BlockchainTransactionProcessor(validator: SmartContractCertValidator) {
  def submitTransaction(
    txData: Array[Byte],
    signerCerts: Array[X509Certificate],
    trustStore: KeyStore
  ): Either[String, String] = {
    AuditLog.log(s"Transaction submission received, data size: ${txData.length}")
    validator.validateChain(signerCerts, trustStore) match {
      case Valid =>
        val txId = java.util.UUID.randomUUID().toString
        AuditLog.log(s"Transaction $txId committed to ledger")
        Right(txId)
      case Invalid(reason) =>
        AuditLog.log(s"Transaction rejected: $reason")
        Left(reason)
    }
  }
}
